use crate::aap::caps::{http_client, state_read};

struct Node;

const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment lookup (approved grant). The result is deliberately not used:
        // the node's output must not change. Transport failures come back as a
        // value from `fetch` and are ignored.
        let url = format!("{}{}", ENRICH_ENDPOINT, percent_encode(&info.date));
        let _enrichment = http_client::fetch(&url);

        let raw = state_read::get("urls").or_else(|| state_read::get("subscriptions"));
        let urls = match raw {
            Some(text) => parse_urls(&text),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

fn parse_urls(text: &str) -> Vec<String> {
    let trimmed = text.trim();
    let candidates: Vec<String> = if trimmed.starts_with('[') {
        parse_json_string_array(trimmed).unwrap_or_else(|| parse_lines(trimmed))
    } else {
        parse_lines(trimmed)
    };

    let mut out: Vec<String> = Vec::new();
    for c in candidates {
        let c = c.trim();
        if c.is_empty() {
            continue;
        }
        if !out.iter().any(|existing| existing == c) {
            out.push(c.to_string());
        }
    }
    out
}

fn parse_lines(text: &str) -> Vec<String> {
    text.lines()
        .map(|l| l.trim())
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .map(|l| l.to_string())
        .collect()
}

/// Minimal parser for a JSON array of strings. Returns `None` on anything else.
fn parse_json_string_array(text: &str) -> Option<Vec<String>> {
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0usize;
    let n = chars.len();

    let skip_ws = |i: &mut usize| {
        while *i < n && chars[*i].is_whitespace() {
            *i += 1;
        }
    };

    skip_ws(&mut i);
    if i >= n || chars[i] != '[' {
        return None;
    }
    i += 1;
    let mut items = Vec::new();
    skip_ws(&mut i);
    if i < n && chars[i] == ']' {
        i += 1;
        skip_ws(&mut i);
        return if i == n { Some(items) } else { None };
    }

    loop {
        skip_ws(&mut i);
        if i >= n || chars[i] != '"' {
            return None;
        }
        i += 1;
        let mut s = String::new();
        loop {
            if i >= n {
                return None;
            }
            let c = chars[i];
            i += 1;
            match c {
                '"' => break,
                '\\' => {
                    if i >= n {
                        return None;
                    }
                    let e = chars[i];
                    i += 1;
                    match e {
                        '"' => s.push('"'),
                        '\\' => s.push('\\'),
                        '/' => s.push('/'),
                        'b' => s.push('\u{0008}'),
                        'f' => s.push('\u{000C}'),
                        'n' => s.push('\n'),
                        'r' => s.push('\r'),
                        't' => s.push('\t'),
                        'u' => {
                            let hi = read_hex4(&chars, &mut i)?;
                            let code = if (0xD800..0xDC00).contains(&hi) {
                                if i + 1 < n && chars[i] == '\\' && chars[i + 1] == 'u' {
                                    i += 2;
                                    let lo = read_hex4(&chars, &mut i)?;
                                    if !(0xDC00..0xE000).contains(&lo) {
                                        return None;
                                    }
                                    0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00)
                                } else {
                                    return None;
                                }
                            } else {
                                hi
                            };
                            s.push(char::from_u32(code)?);
                        }
                        _ => return None,
                    }
                }
                _ => s.push(c),
            }
        }
        items.push(s);
        skip_ws(&mut i);
        if i >= n {
            return None;
        }
        match chars[i] {
            ',' => {
                i += 1;
            }
            ']' => {
                i += 1;
                skip_ws(&mut i);
                return if i == n { Some(items) } else { None };
            }
            _ => return None,
        }
    }
}

fn read_hex4(chars: &[char], i: &mut usize) -> Option<u32> {
    if *i + 4 > chars.len() {
        return None;
    }
    let mut v = 0u32;
    for k in 0..4 {
        v = v * 16 + chars[*i + k].to_digit(16)?;
    }
    *i += 4;
    Some(v)
}

export!(Node);
